/**
 * End-to-end coverage for the direct-LMDB scan producer (plan: plans/lmdb-native-engine/23-kernel-capability-parity.md,
 * M4). These kernels read the store through a real cursor rather than an in-memory adjacency view, which is what lets
 * them serve patterns no adjacency can express — a variable predicate, a named graph, a repeated variable — and stores
 * whose adjacency cache cannot answer at all.
 */
public class LmdbNativeKernelScanQuadTest {

	private static final String EX = "http://example.com/";

	@TempDir
	File dataDir;

	private SailRepository repository;
	private String previousEnabled;

	@BeforeEach
	public void setUp() {
		previousEnabled = System.setProperty(LmdbNativeJaninoCodegen.ENABLED_PROPERTY, "true");
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			connection.begin();
			connection.add(vf.createIRI(EX, "s1"), vf.createIRI(EX, "p1"), vf.createIRI(EX, "o1"));
			connection.add(vf.createIRI(EX, "s1"), vf.createIRI(EX, "p2"), vf.createIRI(EX, "o2"));
			connection.add(vf.createIRI(EX, "s2"), vf.createIRI(EX, "p1"), vf.createIRI(EX, "o3"));
			// A statement in a named graph, which no adjacency view can express.
			connection.add(vf.createIRI(EX, "s3"), vf.createIRI(EX, "p1"), vf.createIRI(EX, "o4"),
					vf.createIRI(EX, "g1"));
			// A self-referencing statement, the repeated-variable case.
			connection.add(vf.createIRI(EX, "s4"), vf.createIRI(EX, "p1"), vf.createIRI(EX, "s4"));
			connection.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
		if (previousEnabled == null) {
			System.clearProperty(LmdbNativeJaninoCodegen.ENABLED_PROPERTY);
		} else {
			System.setProperty(LmdbNativeJaninoCodegen.ENABLED_PROPERTY, previousEnabled);
		}
	}

	@Test
	public void scanWithAVariablePredicateReadsEveryQuad() throws Exception {
		// ?s ?p ?o — no adjacency view exists for a variable predicate, and no root scan is expressible through one.
		Kernel ir = new Kernel(3,
				List.of(new ScanQuad(0, new Operand[] { null, null, null, null }, new int[] { 0, 1, 2, -1 })),
				new Emit(new int[] { 0, 1, 2 }, false, OutputMods.none()));
		assertTrue(ir.resumable, "an unbounded scan must stream rather than materialize the store");
		List<long[]> rows = run(ir, 5);
		assertEquals(5, rows.size(), "every statement, including the named-graph one, must be produced");
	}

	@Test
	public void scanRestrictedToOnePredicateAndOneGraph() throws Exception {
		try (SailDataset dataset = openDataset()) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			ValueFactory vf = repository.getValueFactory();
			long p1 = source.idOf(vf.createIRI(EX, "p1"));
			long g1 = source.idOf(vf.createIRI(EX, "g1"));

			// GRAPH <g1> { ?s <p1> ?o } — the context term is exactly what the adjacency guards reject.
			Kernel ir = new Kernel(2,
					List.of(new ScanQuad(0, new Operand[] { null, Operand.constant(0), null, Operand.constant(1) },
							new int[] { 0, -1, 1, -1 })),
					new Emit(new int[] { 0, 1 }, false, OutputMods.none()));
			List<long[]> rows = runOn(source, ir, new long[] { p1, g1 }, 8);
			assertEquals(1, rows.size(), "only the named-graph statement matches");
			assertEquals(source.idOf(vf.createIRI(EX, "s3")), rows.get(0)[0]);
			assertEquals(source.idOf(vf.createIRI(EX, "o4")), rows.get(0)[1]);
		}
	}

	@Test
	public void scanStreamsIdenticallyAtEveryBufferSize() throws Exception {
		Kernel ir = new Kernel(3,
				List.of(new ScanQuad(0, new Operand[] { null, null, null, null }, new int[] { 0, 1, 2, -1 })),
				new Emit(new int[] { 0, 1, 2 }, false, OutputMods.none()));
		List<long[]> reference = run(ir, 64);
		for (int maxRows : new int[] { 1, 2, 3 }) {
			List<long[]> rows = run(ir, maxRows);
			assertEquals(render(reference), render(rows), "drained " + maxRows + " row(s) at a time");
		}
	}

	/**
	 * Two scan sites, the inner one correlated to a column the outer produced. This is the shape the lowering will
	 * generate for a joined pattern, and it is where the scanner's "one probe per scan site" rule earns its keep: a
	 * probe's iterator dies on that probe's next {@code open}, so if both sites shared a probe the inner scan's first
	 * re-aim would invalidate the outer scan mid-iteration and rows would vanish without any error.
	 */
	@Test
	public void nestedCorrelatedScansDoNotInvalidateEachOther() throws Exception {
		try (SailDataset dataset = openDataset()) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			ValueFactory vf = repository.getValueFactory();
			long p1 = source.idOf(vf.createIRI(EX, "p1"));
			long p2 = source.idOf(vf.createIRI(EX, "p2"));

			// ?s <p1> ?m . ?s <p2> ?t — the inner scan re-opens once per outer row.
			Kernel ir = new Kernel(3,
					List.of(new ScanQuad(0, new Operand[] { null, Operand.constant(0), null, null },
							new int[] { 0, -1, 1, -1 }),
							new ScanQuad(1, new Operand[] { Operand.col(0), Operand.constant(1), null, null },
									new int[] { -1, -1, 2, -1 })),
					new Emit(new int[] { 0, 1, 2 }, false, OutputMods.none()));
			assertEquals(2, ir.requirements.scans, "each scan site needs its own probe");

			// Only s1 has both p1 and p2, so exactly one row survives the join.
			long s1 = source.idOf(vf.createIRI(EX, "s1"));
			long o1 = source.idOf(vf.createIRI(EX, "o1"));
			long o2 = source.idOf(vf.createIRI(EX, "o2"));
			for (int maxRows : new int[] { 1, 2, 8 }) {
				List<long[]> rows = runOn(source, ir, new long[] { p1, p2 }, maxRows);
				assertEquals(1, rows.size(), "drained " + maxRows + " at a time: exactly one joined row");
				assertEquals(s1, rows.get(0)[0]);
				assertEquals(o1, rows.get(0)[1]);
				assertEquals(o2, rows.get(0)[2]);
			}
		}
	}

	/**
	 * Contract test, and a trap the lowering must avoid: {@code -1} in a scan term means <em>unbound</em>, so a term
	 * that fails to resolve does not restrict the scan — it widens it to match everything in that position.
	 *
	 * A query constant absent from the value store resolves to that same sentinel. If a lowering were to pass it
	 * through as a scan term, {@code ?s <p_absent> ?o} would quietly become {@code ?s ?p ?o} and return the whole store
	 * instead of nothing. The interpreted path avoids this by compiling an absent constant to an empty plan, and any
	 * {@code ScanQuad} lowering must do the equivalent before emitting the node. This test pins the sentinel's meaning
	 * so the hazard is visible rather than folklore.
	 */
	@Test
	public void anUnresolvedTermWidensTheScanInsteadOfEmptyingIt() throws Exception {
		try (SailDataset dataset = openDataset()) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			ValueFactory vf = repository.getValueFactory();
			long p1 = source.idOf(vf.createIRI(EX, "p1"));
			long absent = source.idOf(vf.createIRI(EX, "p_absent"));
			assertEquals(NativeLmdbQuerySource.UNKNOWN_ID, absent,
					"a constant missing from the value store resolves to the unbound sentinel");

			Kernel ir = new Kernel(3,
					List.of(new ScanQuad(0, new Operand[] { null, Operand.constant(0), null, null },
							new int[] { 0, -1, 1, -1 }),
							new ScanQuad(1, new Operand[] { Operand.col(0), Operand.constant(1), null, null },
									new int[] { -1, -1, 2, -1 })),
					new Emit(new int[] { 0, 1, 2 }, false, OutputMods.none()));
			List<long[]> rows = runOn(source, ir, new long[] { p1, absent }, 8);
			assertTrue(rows.size() > 0,
					"the unbound sentinel must widen the inner scan, not empty it — a lowering that forwards an "
							+ "unresolved constant would silently return unrestricted results");
		}
	}

	/**
	 * The genuine no-match case, distinguished from the one above: a real, resolvable predicate that the outer subjects
	 * simply do not carry. Those outer rows must contribute nothing and must not disturb the iteration.
	 */
	@Test
	public void correlatedScanContributesNothingForOuterRowsWithoutAMatch() throws Exception {
		try (SailDataset dataset = openDataset()) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			ValueFactory vf = repository.getValueFactory();
			long p1 = source.idOf(vf.createIRI(EX, "p1"));
			long p2 = source.idOf(vf.createIRI(EX, "p2"));

			// Four subjects carry p1; only s1 also carries p2, so three outer rows must join to nothing.
			Kernel ir = new Kernel(3,
					List.of(new ScanQuad(0, new Operand[] { null, Operand.constant(0), null, null },
							new int[] { 0, -1, 1, -1 }),
							new ScanQuad(1, new Operand[] { Operand.col(0), Operand.constant(1), null, null },
									new int[] { -1, -1, 2, -1 })),
					new Emit(new int[] { 0, 1, 2 }, false, OutputMods.none()));
			assertEquals(1, runOn(source, ir, new long[] { p1, p2 }, 8).size(),
					"outer rows whose correlated scan finds nothing must drop out silently and completely");
		}
	}

	private SailDataset openDataset() {
		return NativeQuerySourceAccess.openExplicitDataset((LmdbStore) repository.getSail());
	}

	private List<long[]> run(Kernel ir, int maxRows) throws Exception {
		try (SailDataset dataset = openDataset()) {
			return runOn((NativeLmdbQuerySource) dataset, ir, new long[0], maxRows);
		}
	}

	private static List<long[]> runOn(NativeLmdbQuerySource source, Kernel ir, long[] constants, int maxRows)
			throws Exception {
		Object owner = new Object();
		JaninoKernel kernel = LmdbNativeJaninoCodegen.kernel(owner, ir.shapeKey(), ir.className(),
				() -> LmdbNativeKernelEmitter.emit(ir), Long.MAX_VALUE);
		if (kernel == null) {
			kernel = LmdbNativeJaninoCodegen.awaitKernel(owner, ir.shapeKey(), 30, TimeUnit.SECONDS);
		}
		assertNotNull(kernel, "kernel did not compile; source:\n" + LmdbNativeKernelEmitter.emit(ir));
		LmdbNativeKernelScanner scanner = new LmdbNativeKernelScanner(source, ir.requirements.scans);
		try {
			kernel.bind(new KernelContext(new NativeLmdbQuerySource.NativeAdjacency[0], constants, new long[0],
					new long[0][], null, scanner));
			int stride = ir.stride();
			long[] buffer = new long[stride * maxRows];
			List<long[]> rows = new ArrayList<>();
			while (true) {
				int filled = kernel.fill(buffer, maxRows);
				if (filled == 0) {
					break;
				}
				for (int r = 0; r < filled; r++) {
					rows.add(Arrays.copyOfRange(buffer, r * stride, (r + 1) * stride));
				}
			}
			return rows;
		} finally {
			kernel.close();
			scanner.close();
		}
	}

	private static List<String> render(List<long[]> rows) {
		List<String> rendered = new ArrayList<>();
		for (long[] row : rows) {
			rendered.add(Arrays.toString(row));
		}
		rendered.sort(String::compareTo);
		return rendered;
	}
}
